    return false;

  switch (tag_) {
    case Tag::kObfuscatedGaia:
      return mojo::Equals(*(data_.obfuscated_gaia), *(other.data_.obfuscated_gaia));
    case Tag::kPhoneNumber:
      return mojo::Equals(*(data_.phone_number), *(other.data_.phone_number));
    case Tag::kAccountName:
      return mojo::Equals(*(data_.account_name), *(other.data_.account_name));
  }

